## Where

Node.js v22.13.0 (Mac OSX M2)

## How

```javascript
import Queue from 'fastq'

const worker = ms => {
  return new Promise((resolve, reject) =>
    setTimeout(resolve, ms),
  )
}

const queue = Queue.promise(worker, 2)

for (let i = 0; i < 10; i++) {
  queue.push(1000)
}

setTimeout(() => {
  queue.pause()
}, 3000)

console.time()
await queue.drained() // Warning: Detected unsettled top-level await
console.timeEnd()
```

## Why

I tried to create a "process until disconnection" queue. The full connection routine tries to process the whole queue before marking it as ready, but inside this routine something could fail (I like networks).

I supposed (wrongly) that the `drained` method will just exit if the queue is paused.

I can workaround this "limitation", but I see some potential feature for other `Promise` utilizers :)

The drain() callback seems to work correctly, however the promise returned by drained() gets resolved before any async work has been done.

Example:

```js
const fastq = require('fastq');

(async () => {
    async function prosessTask() {
      await new Promise(resolve => setTimeout(resolve, 0));
      console.log('processed');
    }
    
    try{
      const queue = fastq.promise(prosessTask, 1); // run sequentially
      queue.drain = () => console.log('called drain');
      queue.drained().then( () => console.log('drained promise resolved') );
    
      await Promise.all([queue.push(), queue.push(), queue.push()]);
    }catch(err){
        console.error(err);
    }
})();

```

The output logs I'm getting look like this:

```
drained promise resolved
processed
processed
processed
called drain
```

I would have expected:
```
processed
processed
processed
called drain
drained promise resolved
```

The statement seems not correct (node v20.x):

> This promise could be ignored as it will not lead to a `'unhandledRejection'`.


```js
const queue = require('fastq').promise(worker, 1);

async function worker (arg) {
  throw new Error('app error');
}

process.on('unhandledRejection', (err) => {
  console.error({ unhandledRejection: err });
});

async function run () {
  const result = await queue.push(42);
  console.log('the result is', result);
}

run();
```

Output:

```
{
  unhandledRejection: Error: app error....
}
```

I've found some scenarios where the specified concurrency won't be respected.

1. When a queue with active workers is paused and resumed it starts `concurrency` more workers, regardless of how many are already running: https://github.com/mcollina/fastq/blob/b8d99205b36f9a0e8063ab9c84f6a92757d59ced/queue.js#L80-L83 E.g. the following will have multiple workers running in parallel, even though the concurrency is set to just `1`:
    ```js
    const queue = require('fastq')((i, cb) => {
      console.log({worker: i, running: queue.running()});
      setTimeout(cb, 1000)
    }, 1);

    for (let i = 0; i < 20; i++ ) {
      queue.push(i);
    }

    queue.pause();
    queue.resume();
    ```
    Every subsequent call to `queue.pause(); queue.resume();` will cause one more worker to start running in parallel.

2. Changes to the concurrency are supported according to https://github.com/mcollina/fastq/blob/b8d99205b36f9a0e8063ab9c84f6a92757d59ced/README.md?plain=1#L234C6-L235. However, doing so while the queue has active workers has no effect either way:
    ```js
    const queue = require('fastq')((i, cb) => {
      console.log({worker: i, running: queue.running()});
      setTimeout(cb, 1000)
    }, 1);

    for (let i = 0; i < 20; i++ ) {
      queue.push(i);
    }

    queue.concurrency = 5;
    ```
    ```js
    const queue = require('fastq')((i, cb) => {
      console.log({worker: i, running: queue.running()});
      setTimeout(cb, 1000)
    }, 5);

    for (let i = 0; i < 20; i++ ) {
      queue.push(i);
    }

    queue.concurrency = 1;
    ```

3. Even worse, changing the concurrency to a number lower than the count of currently running workers can cause all subsequently added tasks to be run in parallel:
    ```js
    const queue = require('fastq')((i, cb) => {
      console.log({worker: i, running: queue.running()});
      setTimeout(cb, 1000)
    }, 2);

    queue.push(0);
    queue.push(1);

    queue.concurrency = (queue.running() - 1);

    for (let i = 2; i < 20; i++ ) {
      queue.push(i);
    }
    ```

4. Changing the concurrency to some non-sensical value like `-1` or `1.2` has the same effect. Setting it initially to a value less than one causes an error to be thrown, but changing it later to that is allowed just fine.

I'd be happy to make a pull request that addresses these scenarios, just wanted to hear your thoughts first.

In order to maintain the current API we could make use of a `getter` and `setter` for the concurrency so that changing it can have the side-effect of running extra workers. Killing currently running workers of course still won't be supported since we can't stop arbitrary running functions in JavaScript.

But if you'd prefer to change the API and have the concurrency changed by a call to `queue.concurrency()` then I'd implement it like that.

```js
import fastq from 'fastq';

const worker = async ({ index, retries }) => {
  console.log({ index, retries });
  throw new Error('Oops');
};

const queue = fastq.promise(worker, 1);

queue.error((err, { index, retries }) => {
  if (err) {
    if (retries) {
      queue.unshift({ index, retries: retries - 1 });
      // queue.push({ index, retries: retries - 1 });
    } else {
      console.log({ err }, 'all retries failed');
    }
  }
});

queue.push({ index: 0, retries: 3 });

await queue.drain();
```

I would like to implement a simple retry mechanism with fastq(1.15.0)'s error handler, like every task got 3 more chances. So for the following tries, I would prefer them to be `unshift`ed into the queue. But the log looks like:

```
{ index: 0, retries: 3 }
{ index: 0, retries: 2 }
```

What I expected is the log like this which is replacing `unshift()` with `push()` :

```
{ index: 0, retries: 3 }
{ index: 0, retries: 2 }
{ index: 0, retries: 1 }
{ index: 0, retries: 0 }
{
  err: Error: Oops
      at worker (file:///home/agu/workspace/TimeFabric/livefeed/api/src/queDemo.js:5:9)
      at asyncWrapper (/home/agu/workspace/TimeFabric/livefeed/api/node_modules/fastq/queue.js:213:12)
      at Task.release (/home/agu/workspace/TimeFabric/livefeed/api/node_modules/fastq/queue.js:149:16)
      at worked (/home/agu/workspace/TimeFabric/livefeed/api/node_modules/fastq/queue.js:201:10)
} all retries failed
```

so the worker got executed 4 times before giving up. 

I do not know why `unshift` only got the work executed once. But `unshift` is what I want in this queue, because an immediate retry may just get it done. It does not have to `retry it later` or `wait all over again`.

I created a promised queue, fastq.promise(), with an async worker that may go sideways. So as in regular promise functions, throwing a error would be enough. 

```js
const worker = async () => {
    throw new Error('worker' failed);
};
```

But the queue failed to catch it and I would get `UnhandledPromiseRejectionWarning`. Another fact is that the errorHandler does not catch it, even it is triggered on every single run, as described on #41 .

Your documentation didn't help me understand how to use the `drain` function to wait until the queue is fully processed.

What I came up with is:

```
const queue = fastq.promise(renderDocumentInQueue,
                            config.concurrency);

const waitFor = [];
for (let entry of filez) {
    waitFor.push(queue.push(entry));
}

await Promise.all(waitFor);
```

This is using the Promise version of `fastq`.  In that version, the `push` method returns a Promise.  Therefore pushing the Promise's into an array lets us use Promise.all to know when all tasks have been completed.

Does this look correct?

An alternative I've coded but haven't tested is:

```
// await new Promise((resolve, reject) => {
//    queue.drain = function() {
//        resolve();
//    }
// });
```

It seems from your test scripts that one simply assigns a function to the `drain` field, and it'll automatically be called.  Therefore one way to wait for this function to be called is this Promise here.

Is either preferable over the other?

My impression of error handler was, that it would handle the error and not pass it on. The error handler is called also every time (with error == null).

* I would expect error only being called on error
* and I would expect that the error handler would suppress the error reporting up the chain

Am I setting up the queue wrong or should I write a worker wrapper for suppressing/handling the error? Thanks for some insight, looking forward to the "broken promise" talk! Head is spinning :-) 

```
var queue = require("fastq").promise(worker, 1);

queue.error(function (err, task) {
  console.log("Error is ", err);
  console.log("Task is ", task);
});

async function worker(arg) {
  if (arg == 84) {
    throw new Error("just an error");
  }
  return arg * 2;
}

async function run() {
  const result = await queue.push(42);
  console.log("the result is", result);
  const result2 = await queue.push(84);
  console.log("the result is", result2);
}

run();
```

I got this library working in sync but how do you use it with async?

`typeNames `will never be set because I don't know how to await for the finished result.

Thanks.

```

const typeNames = await getAllTypeNamesById(typeIds)

// This will fire before the queue is finished
console.log('getAllTypeNamesById result:', typeNames)

...

async function getAllTypeNamesById (typeIds) {

  const queue = fastq(worker, 2)

  let items = new Set()

  for (let i = 0; i < typeIds.length; i++) {
    try {

        queue.push(typeIds[i], function (err, result) {
          if (err) { throw err }

          console.log(queue.length(), 'items left')

          if (queue.length() === 0) {
            console.log('Queue is empty!')
          }

        })
      
    } catch (error) {
      
      console.log(error)

    }
  }

  // This will never fire
  return [...items]

  async function worker (typeId, cb) {
    console.log('Resolving name for typeId ' + typeId)

    const { data } = await universeApi.getTypeNameById(typeId)

    cb(null,
      items.add({
        name: data.name,
        type_id: typeId
      })
    )
  }
}
```

> fastq is API compatible with async.queue

Async queue, supports batch-wise processing. i.e.

```js
const { queue } = require("async");

const q = queue(function (task, callback) {
  console.log(2 * task);
  callback();
}, 1);

// accepts array as arg for batchwise processing
q.push([2, 3, 4], function (err) {
  console.log("finished processing item");
});
```

Ref: https://github.com/caolan/async/blob/master/lib/internal/queue.js#L159

in order to be compatible with the async.queue API, it would be nice to have a .error method like specified in async doc:

```
// assign an error callback
q.error(function(err, task) {
    console.error('task experienced an error');
});

```
